<script setup>
import {computed,reactive,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import ChartPanel from '../../components/ChartPanel.vue'
import DataTable from '../../components/DataTable.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import Pagination from '../../components/Pagination.vue'
import {stamp,shortStamp,day,readingNumber,readingFacts,qualityNames} from '../fields/resourceUi.js'
const r=useIrrigation(),route=useRoute(),clock=useClock(),ui=useListState('monitor',{filters:{zoneId:'',pointId:'',depth:20,date:clock.isReference?day(clock.displayNow.value):clock.today.value}}),draft=reactive({...ui.filters})
const e=computed(()=>r.state.entities),zones=computed(()=>e.value.IrrigationZone??[]),soilPoints=computed(()=>(e.value.Point??[]).filter(p=>p.kind==='SOIL_MOISTURE')),zonePoints=computed(()=>soilPoints.value.filter(p=>p.zoneId===draft.zoneId)),depths=computed(()=>[...new Set(zonePoints.value.map(p=>p.depthCm))].sort((a,b)=>a-b)),candidates=computed(()=>zonePoints.value.filter(p=>p.depthCm===Number(draft.depth))),point=computed(()=>soilPoints.value.find(p=>p.pointId===ui.filters.pointId)),readings=computed(()=>(e.value.TelemetryReading??[]).filter(rd=>rd.pointId===ui.filters.pointId&&point.value?.depthCm===Number(ui.filters.depth)&&day(rd.observedAt)===ui.filters.date).sort((a,b)=>Date.parse(b.observedAt)-Date.parse(a.observedAt))),current=computed(()=>readings.value[0]),ascending=computed(()=>[...readings.value].reverse())
function changeZone(){const p=soilPoints.value.find(p=>p.zoneId===draft.zoneId&&p.depthCm===Number(draft.depth))??zonePoints.value[0];draft.pointId=p?.pointId??'';draft.depth=p?.depthCm??20}
function changeDepth(){draft.pointId=candidates.value.find(p=>p.pointId===draft.pointId)?.pointId??candidates.value[0]?.pointId??''}
function changePoint(){draft.depth=zonePoints.value.find(p=>p.pointId===draft.pointId)?.depthCm??draft.depth}
function query(){ui.filters={...draft};ui.page=1;ui.selectedId=null}
watch(()=>[route.query.pointId,route.query.zoneId,route.query.date],()=>{const requested=soilPoints.value.find(p=>p.pointId===route.query.pointId);if(requested){draft.zoneId=requested.zoneId;draft.pointId=requested.pointId;draft.depth=requested.depthCm;draft.date=route.query.date??draft.date;query()}else if(!draft.pointId){const p=soilPoints.value.find(p=>clock.isReference?p.pointId==='PT-JZ-S7KA':true);draft.zoneId=route.query.zoneId??p?.zoneId??zones.value[0]?.zoneId;changeZone();query()}},{immediate:true})
const currentFacts=computed(()=>readingFacts(current.value,point.value,e.value.Device?.find(d=>d.deviceId===point.value?.deviceId),clock.displayNow.value))
const chartOptions=computed(()=>({animation:false,tooltip:{trigger:'item',formatter:p=>`${stamp(p.value[0])}<br/>含水率：${p.value[1]??'无效'} %VWC`},grid:{left:45,right:18,top:28,bottom:32},xAxis:{type:'time',axisLabel:{formatter:value=>new Date(value).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})},splitLine:{show:true,lineStyle:{color:'#e4eeee'}},axisLine:{lineStyle:{color:'#b2c9ca'}}},yAxis:{type:'value',name:'含水率 %VWC',scale:true,splitNumber:4,nameTextStyle:{color:'#567880',align:'left'},splitLine:{lineStyle:{color:'#e4eeee'}},axisLabel:{color:'#58777e'}},series:[{type:'line',connectNulls:false,symbolSize:8,lineStyle:{color:'#078c56',width:2},itemStyle:{color:'#078c56'},areaStyle:{color:'#1b9c6120'},data:ascending.value.map(rd=>({value:[Date.parse(rd.observedAt),rd.quality==='VALID'&&Number.isFinite(rd.value)?rd.value:null],readingId:rd.readingId}))}]}))
function chartClick(event){const id=event.data?.readingId;if(!id)return;const index=readings.value.findIndex(rd=>rd.readingId===id);if(index>=0){ui.page=Math.floor(index/15)+1;ui.selectedId=id}}
const columns=[{key:'index',label:'#',width:70},{key:'readingId',label:'读数编号'},{key:'observedAt',label:'采集时间'},{key:'depth',label:'深度 cm'},{key:'value',label:'含水率 %VWC'},{key:'quality',label:'质量'},{key:'ingestedAt',label:'入库时间'}]
</script>
<template><div class="page-stack monitor-screen"><form class="filters" @submit.prevent="query"><label class="filter-field">分区<select v-model="draft.zoneId" @change="changeZone"><option v-for="z in zones" :key="z.zoneId" :value="z.zoneId">{{z.name}}</option></select></label><label class="filter-field">点位<select v-model="draft.pointId" @change="changePoint"><option v-for="p in candidates" :key="p.pointId" :value="p.pointId">{{p.pointId}}</option></select></label><label class="filter-field depth-filter">深度<select v-model.number="draft.depth" @change="changeDepth"><option v-for="depth in depths" :key="depth" :value="depth">{{depth}}cm</option></select></label><label class="filter-field">日期<input v-model="draft.date" type="date"/></label><button class="btn btn-primary">查询</button></form><div class="monitor-upper"><section class="panel current-reading"><h3 class="panel-title">当前读数</h3><template v-if="current"><div class="current-value">{{readingNumber(current.value)}} <small>%VWC</small></div><dl class="data-pairs"><dt>采样时间</dt><dd>{{stamp(current.observedAt)}}</dd><dt>设备点位</dt><dd>{{point.pointId}}</dd><dt>深度</dt><dd>{{point.depthCm}} cm</dd><dt>质量</dt><dd><StatusBadge :status="current.quality"/></dd></dl><p v-if="currentFacts" class="reading-facts warning-text" role="status">{{currentFacts}}</p></template><p v-else class="empty-state">该日期暂无读数</p></section><section class="panel moisture-chart"><h3 class="panel-title">根区含水率变化</h3><ChartPanel v-if="readings.length" :options="chartOptions" :height="222" @chart-click="chartClick"/><p v-else class="empty-state">该点位当前查询范围暂无读数</p></section></div><section class="panel readings-table"><h3 class="panel-title">原始读数明细</h3><DataTable :columns="columns" :rows="readings.slice((ui.page-1)*15,ui.page*15)" row-key="readingId" :selected-id="ui.selectedId" compact @row-click="row=>ui.selectedId=row.readingId"><template #cell-index="{index}">{{(ui.page-1)*15+index+1}}</template><template #cell-observedAt="{value}">{{shortStamp(value)}}</template><template #cell-ingestedAt="{value}">{{shortStamp(value)}}</template><template #cell-depth>{{point?.depthCm??'—'}}</template><template #cell-value="{value}">{{readingNumber(value)}}</template><template #cell-quality="{value}">{{qualityNames[value]??'质量未知'}}</template></DataTable><Pagination v-model="ui.page" :total="readings.length" text-buttons/></section></div></template>
<style scoped>.monitor-screen{gap:14px}.monitor-screen .filters{gap:21px;padding:0 3px 5px}.monitor-screen .filters .btn{margin-right:120px;min-width:105px;height:38px}.depth-filter{flex:.8}.monitor-upper{display:grid;grid-template-columns:323px 1fr;gap:20px}.monitor-upper .panel{height:266px;padding:12px 23px}.monitor-upper .panel-title{margin-bottom:9px;font-size:19px}.current-value{height:68px;background:#f0f8f3;border-radius:6px;font-size:44px;font-weight:600;color:#08765a;display:flex;align-items:center;padding-left:16px;gap:12px;margin-bottom:9px}.current-value small{font-size:24px}.current-reading .data-pairs{font-size:14px;gap:7px 18px}.current-reading dd{white-space:nowrap}.reading-facts{font-size:12px;line-height:1.4;margin:4px 0 0}.current-reading:has(.reading-facts){height:auto;min-height:266px}.moisture-chart{padding-left:20px!important;padding-right:20px!important}.readings-table{padding:10px 23px 23px}.readings-table .panel-title{margin-bottom:8px}.readings-table :deep(.data-table td){height:26.7px;border-right:1px solid #e3eaec}.readings-table :deep(.data-table){border:1px solid #dce6e9}.readings-table :deep(.pagination){margin-top:20px}@media(max-width:1200px){.monitor-upper{grid-template-columns:300px 1fr}.monitor-screen .filters .btn{margin-right:0}}@media(max-width:800px){.monitor-upper{grid-template-columns:1fr}}
</style>
